package com.powercms.cms.publish;
import com.fasterxml.jackson.databind.*; import com.powercms.cms.publish.entity.DeployTargetEntity; import org.springframework.stereotype.Component; import java.net.*; import java.net.http.*; import java.time.Duration;
@Component public class DeploymentHealthChecker { private final ObjectMapper mapper; private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build(); DeploymentHealthChecker(ObjectMapper mapper){this.mapper=mapper;}
 public record Result(boolean configured,boolean healthy,String detail){}
 public Result check(DeployTargetEntity target){try{JsonNode c=mapper.readTree(target.getConfig());String raw=c.path("healthCheckUrl").asText("");if(raw.isBlank())return new Result(false,true,"health check not configured");URI uri=URI.create(raw);if(!("http".equalsIgnoreCase(uri.getScheme())||"https".equalsIgnoreCase(uri.getScheme()))||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException("healthCheckUrl must be HTTP(S) without credentials");boolean allowPrivate=c.path("allowPrivateHealth").asBoolean(false);for(InetAddress address:InetAddress.getAllByName(uri.getHost()))if(!allowPrivate&&isPrivate(address))throw new IllegalArgumentException("private health endpoint requires allowPrivateHealth=true");int expected=c.path("expectedStatus").asInt(200);int timeout=Math.max(1,Math.min(30,c.path("healthTimeoutSeconds").asInt(10)));HttpRequest req=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(timeout)).GET().build();var response=client.send(req,HttpResponse.BodyHandlers.discarding());return new Result(true,response.statusCode()==expected,"HTTP "+response.statusCode()+" expected "+expected);}catch(Exception ex){return new Result(true,false,safe(ex.getMessage()));}}
 private boolean isPrivate(InetAddress a){return a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress();} private String safe(String s){if(s==null)return "health check failed";return s.length()>300?s.substring(0,300):s;}
}